#!/usr/bin/env node
'use strict';
/**
 * browser/openvibe-sdk.mjs: ONE self-contained ES module with the browser-safe part of the SDK
 * (everything browser.js exposes: core, auth/browser, registry, modules, realtime, media,
 * community, jobs, tools, projects), for pages with no build step:
 *
 *   <script type="module">
 *     import { createClient, auth, registry } from '/vendor/openvibe-sdk.mjs';
 *   </script>
 *
 * Generated from the CommonJS sources with no dependencies: each file reachable from browser.js
 * becomes a function in a small module table, and its relative require() calls become table
 * lookups. It refuses anything that is not a relative require, a node: import, process.env or a
 * client secret, so server-only code cannot slip in. Checked in; test/bundle.test.js fails when it
 * is stale, and test/browser-entries.test.js scans it like the other browser files.
 *
 *   node scripts/browser-bundle.js           write browser/openvibe-sdk.mjs
 *   node scripts/browser-bundle.js --check   exit 1 if it differs from the sources
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const ENTRY = 'browser.js';
const OUT = path.join(ROOT, 'browser', 'openvibe-sdk.mjs');
const REQUIRE_RE = /require\(\s*'([^']+)'\s*\)/g;
const REFUSE = [
    [/client_secret/, 'mentions client_secret'],
    [/process\.env/, 'reads process.env'],
    [/(?:require\s*\(|from\s+|import\s*\()\s*['"]node:/, 'imports a node: module'],
];

function resolve(fromId, spec) {
    const base = path.posix.normalize(path.posix.join(path.posix.dirname(fromId), spec));
    for (const cand of [base, `${base}.js`, `${base}/index.js`]) {
        const abs = path.join(ROOT, cand);
        if (fs.existsSync(abs) && fs.statSync(abs).isFile()) return cand;
    }
    throw new Error(`${fromId}: cannot resolve ${spec}`);
}

/** Every module reachable from the entry, in a stable depth-first order: [{ id, source, deps }]. */
function collect() {
    const order = [];
    const seen = new Map();
    const visit = (id) => {
        if (seen.has(id)) return;
        const source = fs.readFileSync(path.join(ROOT, id), 'utf8');
        for (const [re, why] of REFUSE) if (re.test(source)) throw new Error(`${id} ${why}: not browser-safe, refusing to bundle`);
        const mod = { id, source, deps: {} };
        seen.set(id, mod);
        order.push(mod);
        for (const [, spec] of source.matchAll(REQUIRE_RE)) {
            if (!spec.startsWith('.')) throw new Error(`${id} requires "${spec}": only relative SDK files may be bundled`);
            mod.deps[spec] = resolve(id, spec);
            visit(mod.deps[spec]);
        }
    };
    visit(ENTRY);
    return order;
}

function render() {
    const version = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version;
    const mods = collect();
    const index = new Map(mods.map((m, i) => [m.id, i]));
    const defs = mods.map((m, i) => {
        const body = m.source.replace(REQUIRE_RE, (_all, spec) => `__load(${index.get(m.deps[spec])})`).replace(/\s+$/, '');
        return `// ── ${i}: ${m.id} ${'─'.repeat(Math.max(3, 60 - m.id.length))}\nfunction (module, exports) {\n${body}\n}`;
    });
    // Load the entry now, the same way Node would, to learn its export names.
    const entry = require(path.join(ROOT, ENTRY));
    const names = Object.keys(entry);
    const namespaces = names.filter((n) => entry[n] && typeof entry[n] === 'object');
    const lines = [];
    for (let i = 0; i < names.length; i += 6) lines.push(`    ${names.slice(i, i + 6).join(', ')},`);
    return `// Generated by scripts/browser-bundle.js from ${ENTRY} (openvibe-sdk ${version}, MIT). Do not edit.
// One self-contained ES module: core at the top level plus the browser-safe subpaths as namespaces
// (${namespaces.join(', ')}). No server-only code: no service tokens, JWT verification, events, identity.
/* eslint-disable */
const __defs = [
${defs.join(',\n')},
];
const __cache = new Array(__defs.length);
function __load(i) {
    if (__cache[i]) return __cache[i].exports;
    const module = { exports: {} };
    __cache[i] = module;
    __defs[i].call(module.exports, module, module.exports);
    return module.exports;
}
const sdk = __load(0);

export const {
${lines.join('\n')}
} = sdk;
export default sdk;
`;
}

function main() {
    const check = process.argv.includes('--check');
    const out = render();
    const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : null;
    if (have === out) return;
    if (check) {
        console.error('stale: browser/openvibe-sdk.mjs (run node scripts/browser-bundle.js)');
        process.exit(1);
    }
    fs.mkdirSync(path.dirname(OUT), { recursive: true });
    fs.writeFileSync(OUT, out);
}

if (require.main === module) main();
module.exports = { render, collect, OUT, REFUSE };
